export * as Timeline from './timeline.tsx';
export type {
  ItemOwnProps as TimelineItemOwnProps,
  ItemProps as TimelineItemProps,
  TimeOwnProps as TimelineTimeOwnProps,
  TimeProps as TimelineTimeProps,
  TimelineStatus,
} from './timeline.tsx';

@layer hj.components {
  /* Customise: --hj-timeline-marker (20px) · --hj-timeline-gap (between steps) */
  .hj-timeline {
    --_m: var(--hj-timeline-marker, 20px);
    margin: 0;
    padding: 0;
    list-style: none;
    font-family: var(--hj-font-sans);
    color: var(--hj-fg);
  }

  .hj-timeline-item {
    --_t: var(--hj-fg-mute);
    position: relative;
    display: grid;
    grid-template-columns: var(--_m) minmax(0, 1fr);
    gap: calc(14px * var(--hj-density));
    padding-bottom: var(--hj-timeline-gap, calc(22px * var(--hj-density)));
  }
  .hj-timeline-item:last-child {
    padding-bottom: 0;
  }
  /* The rail: from under this marker to the next one. */
  .hj-timeline-item:not(:last-child)::before {
    content: '';
    position: absolute;
    top: calc(var(--_m) + 4px);
    bottom: 4px;
    left: calc(var(--_m) / 2 - 0.75px);
    width: 1.5px;
    border-radius: 1px;
    background: var(--hj-line);
  }
  .hj-timeline-item[data-status='done']:not(:last-child)::before {
    background: color-mix(in srgb, var(--hj-accent) 45%, transparent);
  }

  .hj-timeline-marker {
    position: relative;
    display: grid;
    place-items: center;
    width: var(--_m);
    height: var(--_m);
    margin-top: 1px;
    border-radius: var(--hj-radius-pill);
    /* Hollow, but visible on true black: a hairline alone vanishes on ink. */
    box-shadow: inset 0 0 0 1.5px color-mix(in srgb, var(--hj-fg-mute) 55%, transparent);
    background: var(--hj-bg);
    font-size: 12px;
    line-height: 0;
  }
  .hj-timeline-marker > svg {
    width: 1em;
    height: 1em;
    stroke-width: 2.25;
  }
  .hj-timeline-item[data-status='done'] .hj-timeline-marker {
    background: var(--hj-accent);
    box-shadow: none;
    color: var(--hj-on-accent);
  }
  .hj-timeline-item[data-status='failed'] .hj-timeline-marker {
    background: var(--hj-danger-soft);
    box-shadow: inset 0 0 0 1.5px var(--hj-danger);
    color: var(--hj-danger-text);
  }
  /* Current: an accent ring with a dot, and a pulse that stops when motion is reduced. */
  .hj-timeline-item[data-status='current'] .hj-timeline-marker {
    box-shadow: inset 0 0 0 1.5px var(--hj-accent);
  }
  .hj-timeline-item[data-status='current'] .hj-timeline-marker::before {
    content: '';
    width: 8px;
    height: 8px;
    border-radius: var(--hj-radius-pill);
    background: var(--hj-accent);
  }
  .hj-timeline-item[data-status='current'] .hj-timeline-marker::after {
    content: '';
    position: absolute;
    inset: 0;
    border-radius: inherit;
    corner-shape: inherit;
    box-shadow: 0 0 0 1.5px var(--hj-accent);
    opacity: 0;
    animation: hj-timeline-pulse 1600ms var(--hj-ease-out) infinite;
    animation-play-state: var(--hj-ambient);
  }
  @keyframes hj-timeline-pulse {
    from {
      opacity: 0.6;
      transform: scale(1);
    }
    to {
      opacity: 0;
      transform: scale(1.8);
    }
  }

  .hj-timeline-body {
    display: flex;
    flex-direction: column;
    gap: 2px;
    min-width: 0;
  }
  .hj-timeline-title {
    font: var(--hj-type-body);
    letter-spacing: var(--hj-tracking-body);
    color: var(--hj-fg);
  }
  .hj-timeline-item[data-status='pending'] .hj-timeline-title {
    color: var(--hj-fg-dim);
  }
  .hj-timeline-item[data-status='failed'] .hj-timeline-title {
    color: var(--hj-danger-text);
  }
  .hj-timeline-time {
    font: var(--hj-type-mono);
    letter-spacing: var(--hj-tracking-mono);
    font-variant-numeric: tabular-nums;
    color: var(--hj-fg-mute);
  }
  .hj-timeline-relative {
    font-family: var(--hj-font-sans);
    letter-spacing: 0;
  }
  .hj-timeline-description {
    margin: 2px 0 0;
    font-size: 13.5px;
    line-height: 1.5;
    color: var(--hj-fg-dim);
  }
  .hj-timeline-actions {
    display: flex;
    gap: calc(8px * var(--hj-density));
    margin-top: calc(8px * var(--hj-density));
  }
}

'use client';
import { useRender } from '@base-ui/react/use-render';
import * as React from 'react';

import { useHanjiConfig } from '../../system/config.tsx';
import { elementPart } from '../../system/part.tsx';
import type { ElementPartProps } from '../../system/part.tsx';
import { cls, withDefaults } from '../../system/slot.ts';

/** The sequence. Renders `<ol>` — order is the point. */
export const Root: (props: ElementPartProps<'ol'>) => React.ReactElement = elementPart(
  'ol',
  'Timeline.Root',
  'hj-timeline',
);
export const Title: (props: ElementPartProps<'div'>) => React.ReactElement = elementPart(
  'div',
  'Timeline.Title',
  'hj-timeline-title',
);
export const Description: (props: ElementPartProps<'p'>) => React.ReactElement = elementPart(
  'p',
  'Timeline.Description',
  'hj-timeline-description',
);
/** A slot for the step's action — Retry on a failed step, View on a done one. */
export const Actions: (props: ElementPartProps<'div'>) => React.ReactElement = elementPart(
  'div',
  'Timeline.Actions',
  'hj-timeline-actions',
);

export type TimelineStatus = 'done' | 'current' | 'pending' | 'failed';

const STATUS_WORDS: Readonly<Record<TimelineStatus, string>> = {
  done: 'Done',
  current: 'In progress',
  pending: 'Not started',
  failed: 'Failed',
};

export interface ItemOwnProps {
  /** done = filled with a check · current = ring with a live pulse · pending = hollow · failed = danger with ✕. */
  status?: TimelineStatus;
  /** Words read before the step ("Failed"), so status is never only a colour. Defaults to English. */
  statusLabel?: string;
}
export type ItemProps = ItemOwnProps & ElementPartProps<'li'>;

/** One step: its marker on the rail, then Title, Time, Description and Actions. */
export function Item(props: ItemProps): React.ReactElement {
  const config = useHanjiConfig();
  const {
    status = 'pending',
    statusLabel,
    render,
    className,
    children,
    ...rest
  } = withDefaults(config, 'Timeline.Item', props);
  const styled = !config.unstyled;
  const glyph =
    status === 'done' ? config.icons.check : status === 'failed' ? config.icons.x : null;
  return useRender({
    render,
    defaultTagName: 'li',
    props: {
      ...rest,
      'data-status': status,
      'aria-current': status === 'current' ? 'step' : undefined,
      className: cls(config, 'Timeline.Item', 'hj-timeline-item', className) as string | undefined,
      children: (
        <>
          <span className={styled ? 'hj-timeline-marker' : undefined} aria-hidden="true">
            {glyph}
          </span>
          <div className={styled ? 'hj-timeline-body' : undefined}>
            <span className="hj-sr-only">{statusLabel ?? STATUS_WORDS[status]}: </span>
            {children}
          </div>
        </>
      ),
    },
  });
}

export interface TimeOwnProps {
  /** Machine-readable timestamp for the `<time>` element (ISO 8601). */
  dateTime?: string;
  /** A relative phrase shown after the absolute time: "2 min ago", "in 1 week". */
  relative?: string;
}
export type TimeProps = TimeOwnProps & ElementPartProps<'span'>;

/** When: the absolute time (children) and, after it, the relative one. */
export function Time(props: TimeProps): React.ReactElement {
  const config = useHanjiConfig();
  const { dateTime, relative, render, className, children, ...rest } = withDefaults(
    config,
    'Timeline.Time',
    props,
  );
  const styled = !config.unstyled;
  return useRender({
    render,
    defaultTagName: 'span',
    props: {
      ...rest,
      className: cls(config, 'Timeline.Time', 'hj-timeline-time', className) as string | undefined,
      children: (
        <>
          <time dateTime={dateTime}>{children}</time>
          {relative ? (
            <span className={styled ? 'hj-timeline-relative' : undefined}> · {relative}</span>
          ) : null}
        </>
      ),
    },
  });
}
